const fs = await import('node:fs');
const inputPath = process.env.INPUT_PATH;
const outputPath = process.env.OUTPUT_PATH;
if (!inputPath) { throw new Error('Missing INPUT_PATH'); }
if (!outputPath) { throw new Error('Missing OUTPUT_PATH'); }
const xmlContent = await fs.promises.readFile(inputPath, 'utf-8');
globalThis.xmlContent = xmlContent;
globalThis.outputPath = outputPath;

const jspMod = await import('jsparsers');
const jsp = jspMod.default || jspMod;
const xmlParser = jsp.xml();
xmlParser.load(globalThis.xmlContent);
const tomlStr = xmlParser.toml();
globalThis.tomlStr = tomlStr;

const fs = await import('node:fs');
await fs.promises.writeFile(globalThis.outputPath, globalThis.tomlStr, 'utf-8');
console.log(JSON.stringify({ output_path: globalThis.outputPath }));
